{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Never Punt in the 'Dead Zone'",
      "recommendation": "Always go for it on 4th down when the ball is between the opponent's 33 and 42-yard line, regardless of down and distance.",
      "rationale": "Win probability and expected points added (EPA) models overwhelmingly show that punting to gain ~20 yards of net field position carries vastly lower EV than taking a mathematical shot at extending a scoring drive, yet most coaches still punt on 4th and long.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.2,
          "interval_95_low": 0.2,
          "interval_95_high": 2.2,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The effect is well-documented by a large sample of historical play data; extreme deviations are unlikely since the situation only arises a few times per game."
        },
        "parameters": {
          "mu": 1.2,
          "sigma": 0.51,
          "conversion_note": "mu = most_plausible_value (1.2). sigma = (2.2 - 0.2) / (2 * 1.96) = 0.510."
        },
        "consistency_check": "most_plausible_value (1.2) is exactly centered in [0.2, 2.2]. The normal distribution has unbounded real support, matching the signed quantity."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Extreme Early-Down Passing",
      "recommendation": "Pass the ball on 80% of 1st-and-10 situations in the first three quarters.",
      "rationale": "Public analytics consistently demonstrate that passing on early downs yields higher EPA per play than running, preventing negative-EV 3rd-and-long situations and maximizing explosive play potential.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.8,
          "interval_95_low": 0.5,
          "interval_95_high": 4.0,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "A right-skewed distribution captures the high upside of clicking early and building blow-out leads, while the downside is somewhat capped by the baseline efficiency of our QB."
        },
        "parameters": {
          "xi": 1.35,
          "omega": 1.30,
          "alpha": 2.2,
          "conversion_note": "Parameters were fit numerically. A location (xi) of 1.35, scale (omega) of 1.30, and shape (alpha) of 2.2 yields a mode near 1.8, with the central 95% mass roughly spanning [0.5, 4.0]."
        },
        "consistency_check": "most_plausible_value (1.8) falls inside [0.5, 4.0]. Support is unbounded real, handling positive and negative effects."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Concede the Run (Light Boxes)",
      "recommendation": "Live in two-high safety shells with 6-man boxes on early downs, daring the opponent to run the ball.",
      "rationale": "Data shows defensive EPA is dictated by preventing explosive passes. Sacrificing 5 yards per carry in the run game is mathematically superior to exposing single-high coverages to 30-yard pass completions.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 2.0,
          "interval_95_low": -1.0,
          "interval_95_high": 5.0,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "While generally optimal, there is a non-trivial chance a dominant opposing rushing attack exploits this so heavily that it dictates the entire game script, resulting in heavy downside tails."
        },
        "parameters": {
          "nu": 4.0,
          "mu": 2.0,
          "sigma": 1.08,
          "conversion_note": "Used t_{0.975, 4} ≈ 2.776. mu = most_plausible (2.0). sigma = (5.0 - -1.0) / (2 * 2.776) = 6.0 / 5.552 ≈ 1.08."
        },
        "consistency_check": "most_plausible_value (2.0) is centered in [-1.0, 5.0]. Support covers the entire real line."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Intentional Defensive Encroachment",
      "recommendation": "When trailing by one score late in the 4th quarter and the opponent is running down the clock in FG range, deliberately jump offsides to stop the game clock.",
      "rationale": "By giving up 5 yards, we freeze the clock and preserve a timeout. Public models generally evaluate penalty EPA as strictly negative; they lack the situational granularity to price in the massive clock-stoppage value of a deliberate penalty when bleeding out a game.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.3,
          "interval_95_low": -0.5,
          "interval_95_high": 1.5,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "This is a weak, highly situational candidate. Most games it has zero effect, and occasionally giving up a 1st down via penalty backfires (-0.5), but saving 40 seconds can rarely flip a loss to a win, generating a right-skewed upside tail."
        },
        "parameters": {
          "xi": -0.1,
          "omega": 0.65,
          "alpha": 2.0,
          "conversion_note": "Fitted numerically: shape (alpha) = 2.0 pulls the mode to the right of location (xi) = -0.1, landing the mode near 0.3 and spanning [-0.5, 1.5] for the central 95% of the distribution."
        },
        "consistency_check": "most_plausible_value (0.3) is within the interval [-0.5, 1.5]. Unbounded real support permits both positive and negative values."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Relentless No-Huddle Tempo",
      "recommendation": "Run 100% no-huddle tempo offense on all drives unless killing the clock in the final 4 minutes of the game.",
      "rationale": "I believe compounding physical exhaustion causes drastic late-game defensive busts. Analytics models measure play-level EPA based on down and distance, but are virtually silent on quantifying the cumulative, non-linear impact of fatigue on an opposing defense over 60 minutes.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.5,
          "interval_95_low": -2.0,
          "interval_95_high": 5.0,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "High variance strategy. It either exhausts the opponent leading to blowout wins, or we go 3-and-out in 45 seconds, stranding our own defense on the field to get shelled (heavy tails in both directions)."
        },
        "parameters": {
          "nu": 4.0,
          "mu": 1.5,
          "sigma": 1.26,
          "conversion_note": "Used t_{0.975, 4} ≈ 2.776. mu = most_plausible (1.5). sigma = (5.0 - -2.0) / (2 * 2.776) = 7.0 / 5.552 ≈ 1.26."
        },
        "consistency_check": "most_plausible_value (1.5) is exactly centered in [-2.0, 5.0]. Support is signed."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Extreme DL Rotation",
      "recommendation": "Rotate interior defensive linemen every 3 plays unconditionally, benching star players for up to 45% of total defensive snaps.",
      "rationale": "Analytics relies on cumulative player grades (PFF, WAR), evaluating players over full seasons. It is mixed/silent on the exact per-play efficiency drop-off of an exhausted All-Pro versus a fresh backup; my intuition is that maximum burst from a lesser player exceeds the tired reps of a star.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.8,
          "interval_95_low": -0.2,
          "interval_95_high": 1.8,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The talent downgrade mitigates some of the fatigue advantage, keeping the overall magnitude of the effect constrained to a narrow, roughly symmetric band around a modest positive gain."
        },
        "parameters": {
          "mu": 0.8,
          "sigma": 0.51,
          "conversion_note": "mu = most_plausible_value (0.8). sigma = (1.8 - -0.2) / (2 * 1.96) = 2.0 / 3.92 ≈ 0.510."
        },
        "consistency_check": "most_plausible_value (0.8) is exactly centered in [-0.2, 1.8]. The normal distribution has unbounded real support."
      }
    }
  ]
}
